// Captura
const assunto = $json.subject || "Sem assunto";
const corpoOriginal = $json.text || $json.html || "Sem conteúdo";
const remetente = $json.from || "Desconhecido";
const dataRecebimento = $json.date || new Date().toISOString();

// remove quebras estranhas, múltiplos espaços, assinaturas longas
let corpo = corpoOriginal
  .replace(/(<[^>]+>)/g, "")          // remove tags HTML, caso existam
  .replace(/\r\n/g, "\n")             // uniformiza quebras de linha
  .replace(/\n{3,}/g, "\n\n")         // reduz múltiplas quebras
  .trim();

// CLASSIFICAÇÃO SIMPLES DO EMAIL
let categoria = "geral";

if (corpo.toLowerCase().includes("erro") || corpo.includes("alerta")) {
  categoria = "alerta";
}
if (corpo.toLowerCase().includes("fatura") || corpo.includes("pagamento")) {
  categoria = "financeiro";
}
if (corpo.toLowerCase().includes("vaga") || corpo.toLowerCase().includes("currículo")) {
  categoria = "rh";
}

// EXTRAÇÃO DE PALAVRAS-CHAVE BÁSICAS
const palavrasChave = [];
const padroes = ["erro", "falha", "pagamento", "fatura", "suporte", "urgente", "alerta", "pedido"];

for (const palavra of padroes) {
  if (corpo.toLowerCase().includes(palavra)) {
    palavrasChave.push(palavra);
  }
}

// TEXTO FINAL FORMATADO
const textoFormatado = 
`Assunto: ${assunto}
De: ${remetente}
Data: ${dataRecebimento}

Categoria: ${categoria}
Palavras-chave detectadas: ${palavrasChave.join(", ") || "Nenhuma"}

Corpo formatado:
${corpo}
`;

// RETORNO PARA OS PRÓXIMOS NODES
return {
  json: {
    assunto,
    corpo,
    remetente,
    dataRecebimento,
    categoria,
    palavrasChave,
    textoFormatado
  }
};

String conteudo = 
    "Status: " + $json.get("status") + "\n" +
    "Email: " + $json.get("email") + "\n" +
    "Horário: " + java.time.Instant.now().toString() + "\n";

Map<String, Object> out = new HashMap<>();
out.put("data", conteudo);
return out;

